import { Subscription } from '@azure/event-hubs';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { AppLogger } from '@/common/logger/app-logger';
import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import {
  PartitionInfo,
  performFinalCheckpoints,
} from '@/helpers/eventhub-functions/checkpoint';
import {
  EventHubClients,
  initializeEventHub,
  cleanupEventHub,
} from '@/helpers/eventhub-functions/initialization';
import {
  EnhancedMessageProcessor,
  ProcessingResult,
  MessageProcessor,
} from '@/helpers/eventhub-functions/message-processing';
import {
  createShutdownState,
  ShutdownState,
} from '@/helpers/eventhub-functions/shutdown';
import {
  subscribeToEventHub,
  unsubscribeFromEventHub,
} from '@/helpers/eventhub-functions/subscription';
import { emitSqlEvent } from '@/helpers/events/emit-sql-events';

@Injectable()
export class EventHubSdkResourceDLQService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkResourceDLQService.name,
      userId,
    };
  }

  private clients: EventHubClients | undefined = undefined;

  private subscription: Subscription | undefined = undefined;

  private partitionInfo: Map<string, PartitionInfo> | undefined = undefined;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly logger: AppLogger,
    private readonly eventEmitter: EventEmitter2,
  ) {
    // TelemetryMetrics is initialized in main.ts before NestJS bootstrap
    // No initialization needed here - use the singleton directly
  }

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context =
      EventHubSdkResourceDLQService.createLogContext('initialize');

    try {
      this.logger.log('Initializing resourceDLQ EventHub service', context);

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getResourceDLQConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const enhancedProcessor = this.createMessageProcessor();

      // Wrap enhanced processor to match MessageProcessor interface
      const processor: MessageProcessor = {
        processMessage: async (
          message,
          sequenceNumber,
          partitionId,
          eventCustomProperties,
        ) => {
          await enhancedProcessor.processMessage(
            message,
            sequenceNumber,
            partitionId,
            eventCustomProperties,
          );
        },
      };

      // Configure error recovery
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      // Subscribe to EventHub with enhanced features
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.resourceDLQCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubResourceDLQService',
          topicName: 'resource-dlq',
          // TelemetryMetrics singleton is used directly in message-processing.ts
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          enableCheckpointing: true,
          maxBatchSize: this.configService.commonMaxBatchSize,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'Enhanced resourceDLQ EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced resourceDLQ EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventHubSdkResourceDLQService.createLogContext('cleanup');

    try {
      this.logger.log(
        'Cleaning up Enhanced resourceDLQ EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubResourceDLQService',
          this.logger,
        );
        this.subscription = undefined;
      }

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            checkpointInterval:
              this.configService.resourceDLQCheckpointInterval,
            consumerGroup: this.configService.resourceDLQConsumerGroup,
            eventHubName: this.configService.resourceDLQEventHubName,
            eventHubNamespace: this.configService.resourceDLQEventHubNamespace,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = undefined;
      }

      this.partitionInfo = undefined;

      this.logger.log(
        'Enhanced resourceDLQ EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced resourceDLQ EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to resourceDLQ with validation and masking
   * @returns EnhancedMessageProcessor configured for resourceDLQ processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    return {
      processMessage: async (
        message: {
          [key: string]: number | string | boolean | undefined;
        },
        sequenceNumber: string,
        partitionId?: string,
        eventCustomProperties?: Record<string, unknown>,
      ): Promise<ProcessingResult | void> => {
        const plantCode = String(message?.plant);

        await emitSqlEvent(
          this.logger,
          EventHubSdkResourceDLQService.createLogContext('processMessage'),
          this.eventEmitter,
          message,
          `${eventCustomProperties?.destinationTable}.u`,
        );
        return { plantCode, status: 'processed' };
      },
    };
  }
}

