@Injectable()
export class ShiftTrackingStatusService implements BeforeApplicationShutdown {
  private readonly shiftTrackingStatusBufferByPlant: Map<
    number,
    EntityBuffer<ShiftTrackingStatus>
  >;

  private lastFlushTime: number;

  private readonly bufferConfig: FlushConfig;

  private totalBufferedEvents: number;

  public constructor(
    @InjectRepository(ShiftTrackingStatus)
    private readonly shiftTrackingStatusRepository: Repository<ShiftTrackingStatus>,
    private readonly customLogger: AppLogger,
    private readonly telemetryConfigService: TelemetryConfigService,
    private readonly storedLogger: StoredLoggerService,
    private readonly configService: EventhubSdkConfigService,
  ) {
    this.shiftTrackingStatusBufferByPlant = new Map<
      number,
      EntityBuffer<ShiftTrackingStatus>
    >();
    this.lastFlushTime = Date.now();
    this.totalBufferedEvents = 0;
    this.bufferConfig = {
      maxBatchSize: this.configService.commonMaxBatchSize,
      maxFlushIntervalMs: this.configService.commonUpsertInterval,
    };
  }

  public async beforeApplicationShutdown(): Promise<void> {
    // Flush everything remaining to sql db
    await this.flushBufferToDB();
  }

  @OnEvent('shift_tracking_status.u')
  private async updateByShiftTrackingIdAndPlant(
    payload: ShiftTrackingStatus,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'updateByShiftTrackingIdAndPlant',
      plant: payload.plant,
      service: 'ShiftTrackingStatusService',
    };

    if (!payload)
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    try {
      await this.upsertByComposite(payload, context);
    } catch (error) {
      this.customLogger.error(
        `Error updating shift tracking status record: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  /**
   * Upsert a ShiftTrackingStatus row using composite natural key (plant, resourceId, dateHourFrom).
   * @param payload Incoming shift tracking status payload
   * @param context Logging context
   */
  private async upsertByComposite(
    payload: ShiftTrackingStatus,
    context: JobsLogContext,
  ): Promise<void> {
    const { plant, resourceId, dateHourFrom } = payload;
    try {
      const eventPrimaryKey = `${plant}|${resourceId}|${dateHourFrom}`;
      await this.addEventToBuffer(payload, eventPrimaryKey);
      this.customLogger.debug(
        `Upserted ShiftTrackingStatus composite (${plant}-${resourceId}-${dateHourFrom})`,
        context,
      );
    } catch (error) {
      this.customLogger.debug(
        `Error while upserting ShiftTrackingStatus composite (${plant}-${resourceId}-${dateHourFrom})`,
        context,
      );
      // Unrelated error → rethrow
      throw error;
    }
  }

  //  This is called per partition so while one loop awaits, another loop will execute in case of replica with multiple partitions owned
  private async addEventToBuffer(
    payload: ShiftTrackingStatus,
    eventPrimaryKey: string,
  ): Promise<void> {
    const { plant } = payload;
    const plantBuffer = this.getOrCreateBuffer(plant);
    const existing = plantBuffer.activeList.get(eventPrimaryKey) || {};
    plantBuffer.activeList.set(eventPrimaryKey, {
      ...existing,
      ...payload,
    });
    this.totalBufferedEvents += 1;
    if (
      this.totalBufferedEvents > this.bufferConfig.maxBatchSize ||
      (Date.now() - this.lastFlushTime >=
        this.bufferConfig.maxFlushIntervalMs &&
        this.totalBufferedEvents > 0)
    ) {
      await this.flushBufferToDB();
    }
  }

  private getOrCreateBuffer(plant: number): EntityBuffer<ShiftTrackingStatus> {
    let buffer = this.shiftTrackingStatusBufferByPlant.get(plant);
    if (!buffer) {
      buffer = {
        activeList: new Map(),
      };
      this.shiftTrackingStatusBufferByPlant.set(plant, buffer);
    }
    return buffer;
  }

  // ---------------- FLUSH LOGIC ----------------

  private async flushBufferToDB(): Promise<void> {
    const totalEventsProcessedInBulk = this.totalBufferedEvents;
    const totalRecords: Array<QueryDeepPartialEntity<ShiftTrackingStatus>> = [];
    const listofBufferedPlants: Array<number> = [
      ...this.shiftTrackingStatusBufferByPlant.keys(),
    ];
    for (const plant of listofBufferedPlants) {
      const plantBuffer = this.shiftTrackingStatusBufferByPlant.get(plant);
      if (plantBuffer && plantBuffer.activeList.size > 0) {
        // 🔥 SAFE SWAP
        const records: Array<QueryDeepPartialEntity<ShiftTrackingStatus>> = [
          ...plantBuffer.activeList.values(),
        ];
        plantBuffer.activeList = new Map();

        totalRecords.push(...records);
      }
    }
    this.lastFlushTime = Date.now();
    this.totalBufferedEvents = 0;

    try {
      const sqlStartTime = Date.now();

      const sql = `
SET XACT_ABORT ON;
SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRAN;

DECLARE @json NVARCHAR(MAX);
SET @json = @0;

;WITH Incoming AS (
  SELECT
    plant          = TRY_CAST(j.plant AS INT),
    resource_id    = TRY_CAST(j.resourceId AS NVARCHAR(20)),
    date_hour_from = TRY_CAST(j.dateHourFrom AS DATETIME),
    date_hour_to   = TRY_CAST(j.dateHourTo AS DATETIME),
    speed          = TRY_CAST(j.speed AS NVARCHAR(512)),
    status         = TRY_CAST(j.status AS NVARCHAR(512)),
	updated_at	   = TRY_CAST(j.updatedAt AS DATETIME2)
  FROM OPENJSON(@json) WITH (
    plant           INT             '$.plant',
    resourceId      NVARCHAR(20)    '$.resourceId',
    dateHourFrom    DATETIME        '$.dateHourFrom',
    dateHourTo      DATETIME        '$.dateHourTo',
    speed           NVARCHAR(512)   '$.speed',
    status          NVARCHAR(512)   '$.status',
	updatedAt    	DATETIME2       '$.updatedAt'
  ) AS j
)
  SELECT * INTO #Incoming FROM Incoming;  -- 🔥 MAKE IT PERSIST

-- UPDATE (partial) and INSERT-if-no-newer
-- Any missing field in incoming will not override existing value in the table to avoid erasing data due to partial updates.
-- Missing properties will be null in the incoming table, that's why we check for IS NOT NULL before updating each column.
UPDATE s WITH (UPDLOCK, HOLDLOCK)
SET
  s.speed        = CASE WHEN i.speed        IS NOT NULL THEN i.speed        ELSE s.speed        END,
  s.status       = CASE WHEN i.status       IS NOT NULL THEN i.status       ELSE s.status       END,
  s.updated_at 	 = GETUTCDATE()

FROM dbo.shift_tracking_status AS s
JOIN #Incoming  AS i
  ON s.plant = i.plant
 AND s.resource_id = i.resource_id
 AND s.date_hour_from = i.date_hour_from

WHERE	i.updated_at > s.updated_at;

INSERT INTO dbo.shift_tracking_status (plant, resource_id, date_hour_from, date_hour_to, speed, status, created_at, updated_at)
SELECT i.plant, i.resource_id, i.date_hour_from, i.date_hour_to, i.speed, i.status, GETUTCDATE(), GETUTCDATE()
FROM #Incoming  AS i
WHERE NOT EXISTS (
  SELECT 1 FROM dbo.shift_tracking_status WITH (UPDLOCK, HOLDLOCK)
  WHERE plant = i.plant
    AND resource_id = i.resource_id
    AND date_hour_from = i.date_hour_from
)
COMMIT TRAN;
`;

      await this.shiftTrackingStatusRepository.query(sql, [
        JSON.stringify(totalRecords),
      ]);

      const sqlDuration = Date.now() - sqlStartTime;

      const { enableTelemetry } = this.telemetryConfigService;
      // Track SQL operation metric using the singleton
      if (enableTelemetry) {
        telemetryMetrics.trackEventProcessingDuration(
          sqlDuration,
          PROCESSING_STATUS.SQL,
          '*', // All plants
          'shift-tracking-status',
        );
        telemetryMetrics.trackCounter(
          'event_processed_count',
          totalEventsProcessedInBulk,
          {
            plantCode: '*', // All plants
            status: PROCESSING_STATUS.SQL,
            topic: 'shift-tracking-status',
          },
        );
      }
    } catch (error) {
      await this.flushRecordsToCosmos(totalRecords, `Upsert error ${error}`);
    }
  }

  private async flushRecordsToCosmos(
    records: Array<QueryDeepPartialEntity<ShiftTrackingStatus>>,
    reason?: string,
  ): Promise<void> {
    // Split the records by plant to benefit from Cosmos partition and make it easier to reprocess per plant
    const recordsByPlant = new Map<
      number,
      Array<QueryDeepPartialEntity<ShiftTrackingStatus>>
    >();

    for (const record of records) {
      const plant = Number(record.plant);

      if (!recordsByPlant.has(plant)) {
        recordsByPlant.set(plant, []);
      }

      recordsByPlant.get(plant)?.push(record);
    }
    await Promise.allSettled(
      [...recordsByPlant.entries()].map(([plant, plantRecords]) =>
        this.storedLogger.functionalLog(
          {
            applicationName: 'rsrce-dlq-di',
            context: {
              destinationTable: 'shift_tracking_status',
              reason,
              records: plantRecords,
            },
            errorCode: ERROR_CODES.failedShiftTrackingStatusEvents.code,
            objectId: `EventHub`,
            plant,
            user: '',
          },
          {
            aggregateErrorsByDay: false,
            usefireAndForget: false,
          },
        ),
      ),
    );
  }
}

