    this.totalBufferedEvents += 1;
    if (
      this.totalBufferedEvents > this.bufferConfig.maxBatchSize ||
      (Date.now() - this.lastFlushTime >=
        this.bufferConfig.maxFlushIntervalMs &&
        this.totalBufferedEvents > 0)
    ) {
      await this.flushBufferToDB();
    }
  }

  private getOrCreateBuffer(plant: number): EntityBuffer<ShiftTrackingDtl> {
    let buffer = this.shiftTrackingDtlBufferByPlant.get(plant);
    if (!buffer) {
      buffer = {
        activeList: new Map(),
      };
      this.shiftTrackingDtlBufferByPlant.set(plant, buffer);
    }
    return buffer;
  }

  // ---------------- FLUSH LOGIC ----------------

  public async flushBufferToDB(): Promise<void> {
    const totalEventsProcessedInBulk = this.totalBufferedEvents;
    const totalRecords: Array<QueryDeepPartialEntity<ShiftTrackingDtl>> = [];
    const listofBufferedPlants: Array<number> = [
      ...this.shiftTrackingDtlBufferByPlant.keys(),
    ];
    for (const plant of listofBufferedPlants) {
      const plantBuffer = this.shiftTrackingDtlBufferByPlant.get(plant);
      if (plantBuffer && plantBuffer.activeList.size > 0) {
        // 🔥 SAFE SWAP
        const records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>> = [
          ...plantBuffer.activeList.values(),
        ];
        plantBuffer.activeList = new Map();

        totalRecords.push(...records);
      }
    }
    this.lastFlushTime = Date.now();
    this.totalBufferedEvents = 0;

    try {
      const sqlStartTime = Date.now();

      const sql = `
SET XACT_ABORT ON;
SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRAN;

DECLARE @json NVARCHAR(MAX);
SET @json = @0;

;WITH Incoming AS (
  SELECT
    plant          = TRY_CAST(j.plant AS INT),
    resource_id    = TRY_CAST(j.resourceId AS NVARCHAR(20)),
    date_hour_from = TRY_CAST(j.dateHourFrom AS DATETIME),
    date_hour_to   = TRY_CAST(j.dateHourTo AS DATETIME),
    target_qty	   = TRY_CAST(j.targetQty AS NUMERIC(18,3)),
	real_qty	   = TRY_CAST(j.realQty AS NUMERIC(18,3)),
	material_id	   = TRY_CAST(j.materialId AS NVARCHAR(18)),
	tool_id		   = TRY_CAST(j.toolId AS NVARCHAR(18)),
	sebango_id	   = TRY_CAST(j.sebangoId AS NVARCHAR(4)),
	cycle_time	   = TRY_CAST(j.cycleTime AS NUMERIC(9,3)),
	slowdown	   = TRY_CAST(j.slowdown AS NUMERIC(18,3)),
	shift_code	   = TRY_CAST(j.shiftCode AS CHAR(1)),
	date_shift_start= TRY_CAST(j.dateShiftStart AS DATETIME),
	date_shift_end = TRY_CAST(j.dateShiftEnd AS DATETIME),
	updated_at	   = TRY_CAST(j.updatedAt AS DATETIME2)
  FROM OPENJSON(@json) WITH (
    plant           INT             '$.plant',
    resourceId      NVARCHAR(20)    '$.resourceId',
    dateHourFrom    DATETIME        '$.dateHourFrom',
    dateHourTo      DATETIME        '$.dateHourTo',
    targetQty       NUMERIC(18,3)   '$.targetQty',
    realQty         NUMERIC(18,3)   '$.realQty',
	materialId		NVARCHAR(18)	'$.materialId',
	toolId			NVARCHAR(18)	'$.toolId',
	sebangoId		NVARCHAR(4)		'$.sebangoId',
	cycleTime		NUMERIC(9,3)	'$.cycleTime',
	slowdown		NUMERIC(18,3)	'$.slowdown',
	shiftCode		CHAR(1)			'$.shiftCode',
	dateShiftStart	DATETIME		'$.dateShiftStart',
	dateShiftEnd	DATETIME		'$.dateShiftEnd',
	updatedAt    	DATETIME2       '$.updatedAt'
  ) AS j
)
  SELECT * INTO #Incoming FROM Incoming;  -- 🔥 MAKE IT PERSIST

-- UPDATE (partial) and INSERT-if-no-newer
-- Any missing field in incoming will not override existing value in the table to avoid erasing data due to partial updates.
-- Missing properties will be null in the incoming table, that's why we check for IS NOT NULL before updating each column.
UPDATE s WITH (UPDLOCK, HOLDLOCK)
SET
  s.target_qty        = CASE WHEN i.target_qty        IS NOT NULL THEN i.target_qty        ELSE s.target_qty        END,
  s.real_qty       = CASE WHEN i.real_qty       IS NOT NULL THEN i.real_qty       ELSE s.real_qty       END,
  s.cycle_time       = CASE WHEN i.cycle_time       IS NOT NULL THEN i.cycle_time       ELSE s.cycle_time       END,
  s.slowdown       = CASE WHEN i.slowdown       IS NOT NULL THEN i.slowdown       ELSE s.slowdown       END,
  s.updated_at 	 = GETUTCDATE()

FROM dbo.shift_tracking_dtl AS s
JOIN #Incoming  AS i
  ON s.plant = i.plant
 AND s.resource_id = i.resource_id
 AND s.date_hour_from = i.date_hour_from
 AND s.material_id = i.material_id
 AND s.tool_id = i.tool_id


WHERE	i.updated_at > s.updated_at;

INSERT INTO dbo.shift_tracking_dtl (plant, resource_id, date_hour_from, date_hour_to, target_qty, real_qty, material_id, tool_id, sebango_id, cycle_time, slowdown, shift_code, date_shift_start, date_shift_end, created_at, updated_at)
SELECT i.plant, i.resource_id, i.date_hour_from, i.date_hour_to, i.target_qty, i.real_qty, i.material_id, i.tool_id, i.sebango_id, i.cycle_time, i.slowdown, i.shift_code, i.date_shift_start, i.date_shift_end, GETUTCDATE(), GETUTCDATE()
FROM #Incoming  AS i
WHERE NOT EXISTS (
  SELECT 1 FROM dbo.shift_tracking_dtl WITH (UPDLOCK, HOLDLOCK)
  WHERE plant = i.plant
    AND resource_id = i.resource_id
    AND date_hour_from = i.date_hour_from
	AND material_id = i.material_id
	AND tool_id = i.tool_id
)
COMMIT TRAN;
`;

      await this.shiftTrackingDtlRepository.query(sql, [
        JSON.stringify(totalRecords),
      ]);

      const sqlDuration = Date.now() - sqlStartTime;

      const { enableTelemetry } = this.telemetryConfigService;
      // Track SQL operation metric using the singleton
      if (enableTelemetry) {
        telemetryMetrics.trackEventProcessingDuration(
          sqlDuration,
          PROCESSING_STATUS.SQL,
          '*', // All plants
          'shift-tracking-dtl',
        );
        telemetryMetrics.trackCounter(
          'event_processed_count',
          totalEventsProcessedInBulk,
          {
            plantCode: '*', // All plants
            status: PROCESSING_STATUS.SQL,
            topic: 'shift-tracking-dtl',
          },
        );
      }
    } catch (error) {
      await this.flushRecordsToCosmos(totalRecords, `Upsert error ${error}`);
    }
  }

  private async flushRecordsToCosmos(
    records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>>,
    reason?: string,
  ): Promise<void> {
    // Split the records by plant to benefit from Cosmos partition and make it easier to reprocess per plant
    const recordsByPlant = new Map<
      number,
      Array<QueryDeepPartialEntity<ShiftTrackingDtl>>
    >();

    for (const record of records) {
      const plant = Number(record.plant);

      if (!recordsByPlant.has(plant)) {
        recordsByPlant.set(plant, []);
      }

      recordsByPlant.get(plant)?.push(record);
    }
    await Promise.allSettled(
      [...recordsByPlant.entries()].map(([plant, plantRecords]) =>
        this.storedLogger.functionalLog(
          {
            applicationName: 'rsrce-dlq-di',
            context: {
              destinationTable: 'shift_tracking_dtl',
              reason,
              records: plantRecords,
            },
            errorCode: ERROR_CODES.failedShiftTrackingDtlEvents.code, // Error code dedicated for shift-tracking-dtl events
            objectId: `EventHub`,
            plant: Number(plant),
            user: '',
          },
          {
            aggregateErrorsByDay: false,
            usefireAndForget: false,
          },
        ),
      ),
    );
  }
}

import { DatabaseType } from 'typeorm';
import { MssqlService } from '@/config/database/mssql/mssql.service';
/**
 *
 * @param mssqlConfigService
 */
interface ConnectionOptions {
  encrypt: boolean;
}

interface ConnectionExtra {
  trustServerCertificate: boolean;
  authentication?: {
    type: string;
    options: {
      clientId: string;
    };
  };
}

interface BaseProperties {
  type: DatabaseType;
  host: string;
  port: number;
  database: string;
  options: ConnectionOptions;
  synchronize: boolean;
  lazy: boolean;
  autoLoadEntities: boolean;
  extra: ConnectionExtra;
}

interface ManagedIdentityProperties extends BaseProperties {
  extra: ConnectionExtra & {
    authentication: {
      type: string;
      options: {
        clientId: string;
      };
    };
  };
}

interface SqlAuthProperties extends BaseProperties {
  username: string;
  password: string;
}

type ConnectionProperties = ManagedIdentityProperties | SqlAuthProperties;

/**
 *
 * @param mssqlConfigService - The configuration service containing MSSQL settings.
 * @returns The connection properties for the database.
 */
export function getDatabaseConnectionProperties(
  mssqlConfigService: MssqlService,
): ConnectionProperties {
  const baseProperties: BaseProperties = {
    autoLoadEntities: true,
    database: mssqlConfigService.database,
    extra: {
      trustServerCertificate: true,
    },
    host: mssqlConfigService.host,
    lazy: true,
    options: {
      encrypt: mssqlConfigService.encrypt,
    },
    port: mssqlConfigService.port,
    synchronize: mssqlConfigService.synchronize,
    type: mssqlConfigService.type as DatabaseType,
  };

  if (mssqlConfigService.useManagedIdentity) {
    const managedIdentityProperties: ManagedIdentityProperties = {
      ...baseProperties,
      extra: {
        ...baseProperties.extra,
        authentication: {
          options: {
            clientId: mssqlConfigService.managedIdentityClientId,
          },
          type: 'azure-active-directory-msi-vm',
        },
      },
    };

    return managedIdentityProperties;
  }

  const sqlAuthProperties: SqlAuthProperties = {
    ...baseProperties,
    password: mssqlConfigService.password,
    username: mssqlConfigService.username,
  };

  return sqlAuthProperties;
}

