    TypeOrmModule.forRootAsync({
      imports: [MssqlModule],
      inject: [MssqlService],
      useFactory: getDatabaseConnectionProperties,
    } as TypeOrmModuleAsyncOptions),
  ],
})
export class MssqlDatabaseProviderModule {}

